require_once __DIR__ . '/../../config/config.php'; require_once __DIR__ . '/../../includes/functions.php';
$donations = mysqli_query($conn, 'SELECT id_donasi, nama_donasi, harga_donasi FROM tabel_donasi ORDER BY id_donasi ASC'); require_once __DIR__ . '/../../includes/header.php';
