<section class="page-heading"><div><h2>Daftar Donasi</h2><p>Pilihan donasi yang dapat ditambahkan ke transaksi.</p></div><a class="button" href="<?= e(app_url('pages/donations/add.php')) ?>">Tambah Donasi</a></section>
<?php if (mysqli_num_rows($donations) === 0): ?><p class="alert">Belum ada pilihan donasi.</p><?php else: ?><div class="table-wrapper"><table><thead><tr><th>ID</th><th>Nama Donasi</th><th>Nominal</th><th>Aksi</th></tr></thead><tbody><?php while ($donation = mysqli_fetch_assoc($donations)): ?><tr><td><?= (int) $donation['id_donasi'] ?></td><td><?= e($donation['nama_donasi']) ?></td><td><?= e(format_rupiah((int) $donation['harga_donasi'])) ?></td><td><div class="actions"><a class="button button-secondary" href="<?= e(app_url('pages/donations/edit.php?id=' . (int) $donation['id_donasi'])) ?>">Edit</a><form class="inline-form" method="post" action="<?= e(app_url('process/donations_process.php')) ?>" data-confirm="Pilihan donasi ini akan dihapus bila belum digunakan pada transaksi."><input type="hidden" name="action" value="delete"><input type="hidden" name="id_donasi" value="<?= (int) $donation['id_donasi'] ?>"><button class="button button-danger">Hapus</button></form></div></td></tr><?php endwhile; ?></tbody></table></div><?php endif; mysqli_free_result($donations); require_once __DIR__ . '/../../includes/footer.php'; ?>
